   105	static int
   106	search(regex_t* reg, unsigned char* str, unsigned char* end, int backward)
   107	{
   108	  int r;
   109	  unsigned char *start, *range;
   110	  OnigRegion *region;
   111	
   112	  region = onig_region_new();
   113	
   114	  if (backward != 0) {
   115	    start = end;
   116	    range = str;
   117	  }
   118	  else {
   119	    start = str;
   120	    range = end;
   121	  }
   122	
   123	  r = onig_search(reg, str, end, start, range, region, ONIG_OPTION_NONE);
   124	  if (r >= 0) {
   125	#ifdef STANDALONE
   126	    int i;
   127	
   128	    fprintf(stdout, "match at %d  (%s)\n", r,
   129	            ONIGENC_NAME(onig_get_encoding(reg)));
   130	    for (i = 0; i < region->num_regs; i++) {
   131	      fprintf(stdout, "%d: (%d-%d)\n", i, region->beg[i], region->end[i]);
   132	    }
   133	#endif
   134	  }
   135	  else if (r == ONIG_MISMATCH) {
   136	#ifdef STANDALONE
   137	    fprintf(stdout, "search fail (%s)\n",
   138	            ONIGENC_NAME(onig_get_encoding(reg)));
   139	#endif
   140	  }
   141	  else { /* error */
   142	#ifdef STANDALONE
   143	    char s[ONIG_MAX_ERROR_MESSAGE_LEN];
   144	
   145	    onig_error_code_to_str((UChar* )s, r);
   146	    fprintf(stdout, "ERROR: %s\n", s);
   147	    fprintf(stdout, "  (%s)\n", ONIGENC_NAME(onig_get_encoding(reg)));
   148	#endif
   149	    onig_region_free(region, 1 /* 1:free self, 0:free contents only */);
   150	
   151	    if (r == ONIGERR_STACK_BUG ||
   152	        r == ONIGERR_UNDEFINED_BYTECODE ||
   153	        r == ONIGERR_UNEXPECTED_BYTECODE)
   154	      return -2;
   155	
   156	    return -1;
   157	  }
   158	
   159	  onig_region_free(region, 1 /* 1:free self, 0:free contents only */);
   160	  return 0;
   161	}
