   169	static int
   170	exec(OnigEncoding enc, OnigOptionType options, OnigSyntaxType* syntax,
   171	     char* apattern, char* apattern_end, char* astr, UChar* end, int backward)
   172	{
   173	  int r;
   174	  regex_t* reg;
   175	  OnigErrorInfo einfo;
   176	  UChar* pattern = (UChar* )apattern;
   177	  UChar* str     = (UChar* )astr;
   178	  UChar* pattern_end = (UChar* )apattern_end;
   179	
   180	  EXEC_COUNT++;
   181	  EXEC_COUNT_INTERVAL++;
   182	
   183	  onig_initialize(&enc, 1);
   184	  onig_set_retry_limit_in_search(RETRY_LIMIT);
   185	#ifdef PARSE_DEPTH_LIMIT
   186	  onig_set_parse_depth_limit(PARSE_DEPTH_LIMIT);
   187	#endif
   188	  onig_set_subexp_call_max_nest_level(CALL_MAX_NEST_LEVEL);
   189	
   190	  r = onig_new(&reg, pattern, pattern_end,
   191	               options, enc, syntax, &einfo);
   192	  if (r != ONIG_NORMAL) {
   193	    char s[ONIG_MAX_ERROR_MESSAGE_LEN];
   194	    onig_error_code_to_str((UChar* )s, r, &einfo);
   195	#ifdef STANDALONE
   196	    fprintf(stdout, "ERROR: %s\n", s);
   197	#endif
   198	    onig_end();
   199	
   200	    if (r == ONIGERR_PARSER_BUG ||
   201	        r == ONIGERR_STACK_BUG  ||
   202	        r == ONIGERR_UNDEFINED_BYTECODE ||
   203	        r == ONIGERR_UNEXPECTED_BYTECODE) {
   204	      return -2;
   205	    }
   206	    else
   207	      return -1;
   208	  }
   209	  REGEX_SUCCESS_COUNT++;
   210	
   211	  r = search(reg, pattern, pattern_end, backward);
   212	  if (r == -2) return -2;
   213	
   214	  if (onigenc_is_valid_mbc_string(enc, str, end) != 0) {
   215	    VALID_STRING_COUNT++;
   216	    r = search(reg, str, end, backward);
   217	    if (r == -2) return -2;
   218	  }
   219	
   220	  onig_free(reg);
   221	  onig_end();
   222	  return 0;
   223	}
