   225	static int
   226	alloc_exec(OnigEncoding enc, OnigOptionType options, OnigSyntaxType* syntax,
   227	           int backward, int pattern_size, size_t remaining_size, unsigned char *data)
   228	{
   229	  int r;
   230	  unsigned char *pattern_end;
   231	  unsigned char *str_null_end;
   232	
   233	  // copy first PATTERN_SIZE bytes off to be the pattern
   234	  unsigned char *pattern = (unsigned char *)malloc(pattern_size != 0 ? pattern_size : 1);
   235	  memcpy(pattern, data, pattern_size);
   236	  pattern_end = pattern + pattern_size;
   237	  data += pattern_size;
   238	  remaining_size -= pattern_size;
   239	
   240	#if defined(UTF16_BE) || defined(UTF16_LE)
   241	  if (remaining_size % 2 == 1) remaining_size--;
   242	#endif
   243	
   244	  unsigned char *str = (unsigned char*)malloc(remaining_size != 0 ? remaining_size : 1);
   245	  memcpy(str, data, remaining_size);
   246	  str_null_end = str + remaining_size;
   247	
   248	  r = exec(enc, options, syntax,
   249	           (char *)pattern, (char *)pattern_end,
   250	           (char *)str, str_null_end, backward);
   251	
   252	  free(pattern);
   253	  free(str);
   254	  return r;
   255	}
